import{_ as a,b as e,f as n,I as l}from"./chunks/framework.DYvp_Vyw.js";const u=JSON.parse('{"title":"关于Github Page","description":"vitepress-theme-bluearchive Tags","frontmatter":{"title":"关于Github Page","date":"2025-04-24T08:44:52.000Z","tags":["github"],"head":[["meta",{"name":"description","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/About-Github-Page.md","filePath":"posts/About-Github-Page.md"}'),o={name:"posts/About-Github-Page.md"};function t(i,s,r,p,c,d){return n(),e("div",null,s[0]||(s[0]=[l(`<p>关于第一次使用github Page遇到的一些坑...</p><hr><blockquote><p>PS: 第一次部署直接搞到凌晨4点多...以前没怎么玩过github，有点陌生（悲）</p></blockquote><h1 id="_1-github-pages-简介" tabindex="-1">1.GitHub Pages 简介 <a class="header-anchor" href="#_1-github-pages-简介" aria-label="Permalink to &quot;1.GitHub Pages 简介&quot;">​</a></h1><p>GitHub Pages 是一种用于托管静态网站的服务，用户可以从 GitHub 上的仓库中直接发布网页。它支持自定义域名，并能够使用 Jekyll 等静态站点生成器。</p><h2 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to &quot;主要特性&quot;">​</a></h2><ul><li><strong>免费托管</strong>：GitHub Pages 是免费的，适合个人和项目的网站。</li><li><strong>自定义域名</strong>：可以使用自己的域名。</li><li><strong>支持 Jekyll</strong>：可以使用 Jekyll 进行静态网站生成，方便管理博客和文档。</li><li><strong>HTTPS 支持</strong>：自动提供 HTTPS 以确保安全性。</li></ul><h2 id="创建-github-pages" tabindex="-1">创建 GitHub Pages <a class="header-anchor" href="#创建-github-pages" aria-label="Permalink to &quot;创建 GitHub Pages&quot;">​</a></h2><ol><li><p><strong>创建仓库</strong>：</p><ul><li>在 GitHub 上创建一个新的仓库，命名为 <code>username.github.io</code>，其中 <code>username</code> 是你的 GitHub 用户名。</li></ul><blockquote><p>当然仓库名称没有强制要求，也可以随便取，不过这样的话后面部署后github page给你生成的网址也会长一点</p></blockquote></li><li><p><strong>添加文件</strong>：</p><ul><li>在仓库中添加一个 <code>index.html</code> 文件，或者你可以使用 Markdown 文件（如 <code>README.md</code>）作为主页。</li></ul></li><li><p><strong>启用 GitHub Pages</strong>：</p><ul><li>进入仓库的设置页面，向下滚动到 &quot;GitHub Pages&quot; 部分。</li><li>选择分支（通常是 <code>main</code> 或 <code>gh-pages</code>），然后点击保存。</li></ul></li><li><p><strong>访问你的页面</strong>：</p><ul><li>通过 <code>https://username.github.io</code> 访问你的网站。</li></ul></li></ol><h2 id="使用-markdown" tabindex="-1">使用 Markdown <a class="header-anchor" href="#使用-markdown" aria-label="Permalink to &quot;使用 Markdown&quot;">​</a></h2><p>在 GitHub Pages 中，你可以使用 Markdown 文件来创建内容。Markdown 是一种轻量级标记语言，方便书写格式化文本。</p><h1 id="_2-将前端项目部署到-github-pages" tabindex="-1">2.将前端项目部署到 GitHub Pages <a class="header-anchor" href="#_2-将前端项目部署到-github-pages" aria-label="Permalink to &quot;2.将前端项目部署到 GitHub Pages&quot;">​</a></h1><p>当然，除了以上的用法外，我觉得其最强大的一点就是可以帮忙托管你的前端项目！ 以下是将你的前端项目部署到 GitHub Pages 的步骤。</p><h2 id="步骤-1-创建-github-仓库" tabindex="-1">步骤 1: 创建 GitHub 仓库 <a class="header-anchor" href="#步骤-1-创建-github-仓库" aria-label="Permalink to &quot;步骤 1: 创建 GitHub 仓库&quot;">​</a></h2><ol><li>登录到你的 GitHub 账户。</li><li>点击右上角的 <strong>+</strong> 按钮，然后选择 <strong>New repository</strong>。</li><li>输入仓库名称（可取为 <code>username.github.io</code>，其中 <code>username</code> 是你的 GitHub 用户名），选择 <strong>Public</strong>，然后点击 <strong>Create repository</strong>。</li></ol><blockquote><p>同样的，这里的仓库名其实没有强制要求，不过按照这里写的来最方便。</p></blockquote><h2 id="步骤-2-准备项目" tabindex="-1">步骤 2: 准备项目 <a class="header-anchor" href="#步骤-2-准备项目" aria-label="Permalink to &quot;步骤 2: 准备项目&quot;">​</a></h2><ol><li>在你的本地机器上，创建或打开你的前端项目。</li><li>确保项目中有一个主入口文件，通常是 <code>index.html</code>。</li></ol><blockquote><p>像<strong>Vue</strong>、<strong>React</strong>这样的框架则需要先打包，打包后自然会有一个index.html。</p></blockquote><h2 id="步骤-3-初始化-git" tabindex="-1">步骤 3: 初始化 Git <a class="header-anchor" href="#步骤-3-初始化-git" aria-label="Permalink to &quot;步骤 3: 初始化 Git&quot;">​</a></h2><ol><li>在项目根目录下打开终端。</li><li>初始化 Git 仓库：</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> init</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="3"><li>添加远程仓库:</li></ol><blockquote><p>这里的<strong>repository</strong>是你的仓库名称。</p></blockquote><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> remote</span><span style="color:#2AA198;"> add</span><span style="color:#2AA198;"> origin</span><span style="color:#2AA198;"> https://github.com/username/repository.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="步骤-4-添加和提交文件" tabindex="-1">步骤 4: 添加和提交文件 <a class="header-anchor" href="#步骤-4-添加和提交文件" aria-label="Permalink to &quot;步骤 4: 添加和提交文件&quot;">​</a></h2><ol><li>添加所有文件到 Git：</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> add</span><span style="color:#2AA198;"> .</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>提交更改：</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> commit</span><span style="color:#CB4B16;"> -m</span><span style="color:#2AA198;"> &quot;Initial commit&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="步骤-5-部署到-github-pages" tabindex="-1">步骤 5: 部署到 GitHub Pages <a class="header-anchor" href="#步骤-5-部署到-github-pages" aria-label="Permalink to &quot;步骤 5: 部署到 GitHub Pages&quot;">​</a></h2><ol><li>在终端中，将代码推送到 GitHub：</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> push</span><span style="color:#CB4B16;"> -u</span><span style="color:#2AA198;"> origin</span><span style="color:#2AA198;"> main</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>注意：如果使用的是 <code>master</code> 分支，请替换为 <code>master</code>。</p></blockquote><ol start="2"><li>进入 GitHub 仓库，点击 <strong>Settings</strong>。</li><li>向下滚动到 <strong>GitHub Pages</strong> 部分。</li><li>在 <strong>Source</strong> 下拉菜单中选择 <code>main</code> 或 <code>gh-pages</code> 分支，然后点击 <strong>Save</strong>。</li></ol><h2 id="步骤-6-访问你的-github-pages" tabindex="-1">步骤 6: 访问你的 GitHub Pages <a class="header-anchor" href="#步骤-6-访问你的-github-pages" aria-label="Permalink to &quot;步骤 6: 访问你的 GitHub Pages&quot;">​</a></h2><ul><li>访问 <code>https://username.github.io</code> 查看你的网站。</li></ul><blockquote><p>注意：点击完<strong>Save</strong>后需要等一会，网站才会部署上去，需要等待一段时间(&lt;3分钟)</p></blockquote><hr><h1 id="_3-踩坑经历" tabindex="-1">3.踩坑经历 <a class="header-anchor" href="#_3-踩坑经历" aria-label="Permalink to &quot;3.踩坑经历&quot;">​</a></h1><blockquote><p>前文也说了，没经验，所以开始时第一步创建仓库时是自己起的名称<strong>My-Blog</strong>。</p></blockquote><blockquote><p>以下是我的踩坑经历总结(我部署的是vitepress)</p></blockquote><h2 id="_1-仓库名称自定义" tabindex="-1">1.仓库名称自定义 <a class="header-anchor" href="#_1-仓库名称自定义" aria-label="Permalink to &quot;1.仓库名称自定义&quot;">​</a></h2><ol><li>设置<strong>base</strong>参数</li></ol><p>如果是像我一样仓库名称自定义的话(这里拿<strong>My-Blog</strong>为例)，则在项目打包前需要而外做一件事情，就是在config.mts文件的默认导出中加一项<strong>base</strong>。</p><div class="language-mts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mts</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>base: &#39;/My-Blog/&#39; # 也就是/你自定义的仓库名称/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>因为前文说过了，如果自定义仓库名称的话会导致github page部署完之后给你返回的网址长度更长（也就是在上文标准版的前提下再加上你的自定义仓库名称作为后缀）</p></blockquote><ul><li>标准操作的访问路由： <code>https://username.github.io</code></li><li>自定义仓库名称的访问路由：<code>https://username.github.io/repository/</code></li></ul><h2 id="_2-静态资源路径问题" tabindex="-1">2.静态资源路径问题 <a class="header-anchor" href="#_2-静态资源路径问题" aria-label="Permalink to &quot;2.静态资源路径问题&quot;">​</a></h2><p>由于base路径改变，所有静态资源引用都需要调整：</p><div class="language-mts line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mts</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>// 错误写法（部署后会404）</span></span>
<span class="line"><span>![图片](/public/image.png)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 正确写法（使用绝对路径）</span></span>
<span class="line"><span>![图片](/My-Blog/public/image.png)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_3-路由跳转问题" tabindex="-1">3. 路由跳转问题 <a class="header-anchor" href="#_3-路由跳转问题" aria-label="Permalink to &quot;3. 路由跳转问题&quot;">​</a></h2><p>所有内部链接都需要添加base前缀：</p><div class="language-markdown line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">&lt;!-- 错误写法 --&gt;</span></span>
<span class="line"><span style="color:#839496;">[</span><span style="color:#2AA198;">返回首页</span><span style="color:#839496;">](/)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">&lt;!-- 正确写法 --&gt;</span></span>
<span class="line"><span style="color:#839496;">[</span><span style="color:#2AA198;">返回首页</span><span style="color:#839496;">](/My-Blog/)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>也就等于是要保证项目能够在设置了<strong>base</strong>的情况下依旧能达到原先的效果（不急着打包）。 当改完项目能达到原先的使用效果后，就可以打包了。</p></blockquote><h2 id="_4-准备项目" tabindex="-1">4.准备项目 <a class="header-anchor" href="#_4-准备项目" aria-label="Permalink to &quot;4.准备项目&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">npm</span><span style="color:#2AA198;"> run</span><span style="color:#2AA198;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>执行完后会在<code>.vitepress</code>目录下生成一个<strong>dist</strong> 文件。</p><h2 id="_5-上传文件" tabindex="-1">5.上传文件 <a class="header-anchor" href="#_5-上传文件" aria-label="Permalink to &quot;5.上传文件&quot;">​</a></h2><blockquote><p>这里因为个人原因我选择只上传<strong>dist</strong>而不是上传整个源码+打包文件。</p></blockquote><ol><li>到dist目录下</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">cd</span><span style="color:#2AA198;"> .vitepress/dist</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>​​初始化 Git 仓库​​</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> init</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="3"><li>​​关联远程仓库​​</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> remote</span><span style="color:#2AA198;"> add</span><span style="color:#2AA198;"> origin</span><span style="color:#2AA198;"> https://github.com/你的用户名/仓库名.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="4"><li>​​创建并切换到 gh-pages 分支​​</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> checkout</span><span style="color:#CB4B16;"> -b</span><span style="color:#2AA198;"> gh-pages</span><span style="color:#586E75;font-style:italic;">  # 创建并切换分支</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="5"><li>​​提交所有文件​​</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> add</span><span style="color:#2AA198;"> .</span></span>
<span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> commit</span><span style="color:#CB4B16;"> -m</span><span style="color:#2AA198;"> &quot;首次部署&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ol start="6"><li>​​强制推送到远程​​</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">git</span><span style="color:#2AA198;"> push</span><span style="color:#CB4B16;"> -f</span><span style="color:#2AA198;"> origin</span><span style="color:#2AA198;"> gh-pages</span><span style="color:#586E75;font-style:italic;">  # 首次推送需要-f</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>后面不需要再操作了，<strong>github page</strong>会自动帮我部署，直接等待<strong>github page</strong>给我部署后的链接就行。</p></blockquote><hr>`,74)]))}const g=a(o,[["render",t]]);export{u as __pageData,g as default};
